package com.hepsiburada.testdata;

public class SearchTestData {

    private String searchTerm;
    private int targetRow;
    private int targetProductInRow;

    public String getSearchTerm() {
        return searchTerm;
    }

    public void setSearchTerm(String searchTerm) {
        this.searchTerm = searchTerm;
    }

    public int getTargetRow() {
        return targetRow;
    }

    public void setTargetRow(int targetRow) {
        this.targetRow = targetRow;
    }

    public int getTargetProductInRow() {
        return targetProductInRow;
    }

    public void setTargetProductInRow(int targetProductInRow) {
        this.targetProductInRow = targetProductInRow;
    }
}
